import json

tasks = [
    {
        "task": "A",
        "priority": "high",
        "owner": "Oney"
    },
    {
        "task": "B",
        "priority": "low",
        "owner": "Agent"
    },
    {
        "task": "C",
        "priority": "medium",
        "owner": "Oney"
    }
]

# Normalize to tasks-normalized.json format
normalized_tasks = [
    {
        "task": task["task"],
        "priority": task["priority"].lower(),
        "owner": task["owner"]
    }
    for task in tasks
]

# Write to file
with open('tasks-normalized.json', 'w') as f:
    json.dump(normalized_tasks, f, indent=2)

normalized_tasks

